import { describe, it } from "./helpers/bdd";
import { expect } from "@std/expect";
import {
  MAX_SPACE_ARCHIVE_BYTES,
  readSpaceRepoArchive,
  writeSpaceRepoArchive,
} from "../src/lib/spaces/repo-archive";

// Generated by the reference PDS image at revision 83d473dec69bbf19fe95fcbbb20a39842779db82.
const REPO = "did:plc:ztamizklsl7koph5mbiuuuc4";
const SPACE = `at://${REPO}/space/com.example.note/self`;
const EXPECTED = { space: SPACE, repo: REPO };
const CID = "bafyreie42kbiqjv2iy5mdsnfoogerllgjxlg5qwx3dyydpgykgumpwojsa";
const fixture = () =>
  Deno.readFile(
    new URL("./fixtures/spaces/reference-repo.star", import.meta.url),
  );

describe("Spaces repo archives", () => {
  it("reads and reproduces an archive from the reference PDS", async () => {
    const bytes = await fixture();
    const archive = await readSpaceRepoArchive(bytes, EXPECTED);
    expect(archive.rev).toBe("3n2a5tw2wd22l");
    expect(archive.records).toHaveLength(1);
    expect(archive.records[0]).toMatchObject({
      collection: "com.example.note",
      rkey: "fixture-1",
      cid: CID,
    });
    expect(await writeSpaceRepoArchive(archive)).toEqual(bytes);
  });

  it("rejects a different repo, different space, truncation and tampering", async () => {
    const bytes = await fixture();
    await expect(
      readSpaceRepoArchive(bytes, { ...EXPECTED, repo: "did:plc:other" }),
    ).rejects.toThrow();
    await expect(
      readSpaceRepoArchive(bytes, {
        ...EXPECTED,
        space: `at://${REPO}/space/com.example.note/other`,
      }),
    )
      .rejects.toThrow();
    await expect(readSpaceRepoArchive(bytes.subarray(0, -1), EXPECTED)).rejects
      .toThrow();
    const altered = Uint8Array.from(bytes);
    altered[altered.length - 3] ^= 1;
    await expect(readSpaceRepoArchive(altered, EXPECTED)).rejects.toThrow();
  });

  it("does not emit an archive when the snapshot has an incorrect CID or set hash", async () => {
    const archive = await readSpaceRepoArchive(await fixture(), EXPECTED);
    await expect(writeSpaceRepoArchive({
      ...archive,
      records: [{
        ...archive.records[0],
        cid: "bafyreiaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      }],
    })).rejects.toThrow();
    await expect(
      writeSpaceRepoArchive({ ...archive, data: new Uint8Array(32) }),
    ).rejects.toThrow();
    await expect(
      writeSpaceRepoArchive({
        ...archive,
        records: [archive.records[0], archive.records[0]],
      }),
    )
      .rejects.toThrow();
  });

  it("takes its own copies before awaiting archive serialization or parsing", async () => {
    const bytes = await fixture();
    const reference = Uint8Array.from(bytes);
    const pendingRead = readSpaceRepoArchive(bytes, EXPECTED);
    bytes.fill(0);
    const archive = await pendingRead;
    const pendingWrite = writeSpaceRepoArchive(archive);
    archive.data.fill(0);
    archive.records[0].value.fill(0);
    expect(await pendingWrite).toEqual(reference);
  });

  it("binds the expected repo identity before asynchronous parsing", async () => {
    const expected = {
      space: `at://${REPO}/space/com.example.note/other`,
      repo: "did:plc:other",
    };
    const pending = readSpaceRepoArchive(await fixture(), expected);
    expected.space = SPACE;
    expected.repo = REPO;
    await expect(pending).rejects.toThrow();
  });

  it("rejects archives above the worker memory bound before parsing", async () => {
    await expect(
      readSpaceRepoArchive(
        new Uint8Array(MAX_SPACE_ARCHIVE_BYTES + 1),
        EXPECTED,
      ),
    ).rejects.toThrow();
  });
});
